{"content":"<script setup lang="ts">
import { computed, ref, shallowRef } from "vue";
import catalogData from "../../public/r/registry.json";

interface RegistryFile {
  path: string;
  type: string;
  content?: string;
  target?: string;
}

interface RegistryItem {
  $schema?: string;
  name: string;
  type:
    | "registry:base"
    | "registry:block"
    | "registry:component"
    | "registry:font"
    | "registry:lib"
    | "registry:hook"
    | "registry:ui"
    | "registry:page"
    | "registry:file"
    | "registry:style"
    | "registry:theme"
    | "registry:item";
  title?: string;
  description?: string;
  author?: string;
  dependencies?: string[];
  devDependencies?: string[];
  registryDependencies?: string[];
  files?: RegistryFile[];
  cssVars?: {
    theme?: Record<string, string>;
    light?: Record<string, string>;
    dark?: Record<string, string>;
  };
  css?: Record<string, Record<string, string>>;
  meta?: Record<string, unknown>;
}

type TabKey = "all" | "ui" | "theme" | "hook";

const catalog = shallowRef(catalogData);
const items = computed<RegistryItem[]>(() => catalog.value.items as RegistryItem[]);

const searchQuery = ref("");
const activeTab = ref<TabKey>("all");
const selectedPm = ref<"npx" | "pnpm" | "bun">("npx");
const copiedItem = ref<string | null>(null);
const expandedItem = ref<string | null>(null);

const counts = computed(() => {
  const all = items.value.length;
  const ui = items.value.filter((i) => i.type === "registry:ui").length;
  const theme = items.value.filter((i) => i.type === "registry:theme" || i.type === "registry:base").length;
  const hook = items.value.filter((i) => i.type === "registry:hook").length;
  return { all, ui, theme, hook };
});

const filteredItems = computed(() => {
  const query = searchQuery.value.trim().toLowerCase();
  return items.value.filter((item) => {
    // Tab filter
    if (activeTab.value === "ui" && item.type !== "registry:ui") return false;
    if (activeTab.value === "theme" && item.type !== "registry:theme" && item.type !== "registry:base") return false;
    if (activeTab.value === "hook" && item.type !== "registry:hook") return false;

    // Search query filter
    if (!query) return true;
    const matchName = item.name.toLowerCase().includes(query);
    const matchTitle = (item.title ?? "").toLowerCase().includes(query);
    const matchDesc = (item.description ?? "").toLowerCase().includes(query);
    const matchDeps = (item.dependencies ?? []).some((d) => d.toLowerCase().includes(query));
    return matchName || matchTitle || matchDesc || matchDeps;
  });
});

function getCommand(name: string): string {
  const url = `https://pantoken.app/r/${name}.json`;
  switch (selectedPm.value) {
    case "pnpm":
      return `pnpm dlx shadcn@latest add ${url}`;
    case "bun":
      return `bunx --bun shadcn@latest add ${url}`;
    case "npx":
    default:
      return `npx shadcn@latest add ${url}`;
  }
}

async function copyCommand(name: string) {
  const text = getCommand(name);
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      copiedItem.value = name;
      setTimeout(() => {
        if (copiedItem.value === name) {
          copiedItem.value = null;
        }
      }, 2000);
    } catch {
      // Ignore clipboard error
    }
  }
}

function toggleExpand(name: string) {
  expandedItem.value = expandedItem.value === name ? null : name;
}

function typeBadgeLabel(type: RegistryItem["type"]): string {
  switch (type) {
    case "registry:ui":
      return "UI Component";
    case "registry:theme":
      return "Theme";
    case "registry:base":
      return "Base System";
    case "registry:hook":
      return "Hook";
    default:
      return type.replace(/^registry:/, "");
  }
}
</script>

<template>
  <div class="registry-browser">
    <!-- Header Banner / Info -->
    <div class="registry-hero">
      <div class="registry-hero__badge">
        <span class="instui-tag -color-brand">shadcn/ui Registry</span>
        <a href="/r/registry.json" target="_blank" rel="noopener noreferrer" class="registry-hero__json-link">
          /r/registry.json ↗
        </a>
      </div>
      <p class="registry-hero__desc">
        Compatible components, themes, and behavior hooks formatted according to the shadcn/ui registry specification.
        Add items directly to your shadcn/ui project with your favorite package manager.
      </p>

      <div class="registry-config-tip">
        <span class="registry-config-tip__label">Add directly via CLI:</span>
        <code>npx shadcn@latest add https://pantoken.app/r/[component].json</code>
      </div>
    </div>

    <!-- Controls Toolbar -->
    <div class="registry-toolbar">
      <!-- Search Input -->
      <div class="registry-search">
        <input
          v-model="searchQuery"
          type="search"
          class="registry-search__input"
          placeholder="Search components, themes, hooks..."
          aria-label="Search registry items"
        />
        <button
          v-if="searchQuery"
          class="registry-search__clear"
          type="button"
          aria-label="Clear search"
          @click="searchQuery = ''"
        >
          ✕
        </button>
      </div>

      <!-- Package Manager Selector -->
      <div class="registry-pm-selector">
        <span class="registry-pm-selector__label">CLI:</span>
        <div class="registry-pm-buttons" role="group" aria-label="Package Manager">
          <button
            type="button"
            class="registry-pm-btn"
            :class="{ '-active': selectedPm === 'npx' }"
            @click="selectedPm = 'npx'"
          >
            npx
          </button>
          <button
            type="button"
            class="registry-pm-btn"
            :class="{ '-active': selectedPm === 'pnpm' }"
            @click="selectedPm = 'pnpm'"
          >
            pnpm
          </button>
          <button
            type="button"
            class="registry-pm-btn"
            :class="{ '-active': selectedPm === 'bun' }"
            @click="selectedPm = 'bun'"
          >
            bun
          </button>
        </div>
      </div>
    </div>

    <!-- Category Tabs -->
    <div class="registry-tabs" role="tablist">
      <button
        type="button"
        role="tab"
        class="registry-tab"
        :class="{ '-active': activeTab === 'all' }"
        :aria-selected="activeTab === 'all'"
        @click="activeTab = 'all'"
      >
        All <span class="registry-tab__count">({{ counts.all }})</span>
      </button>
      <button
        type="button"
        role="tab"
        class="registry-tab"
        :class="{ '-active': activeTab === 'ui' }"
        :aria-selected="activeTab === 'ui'"
        @click="activeTab = 'ui'"
      >
        Components <span class="registry-tab__count">({{ counts.ui }})</span>
      </button>
      <button
        type="button"
        role="tab"
        class="registry-tab"
        :class="{ '-active': activeTab === 'theme' }"
        :aria-selected="activeTab === 'theme'"
        @click="activeTab = 'theme'"
      >
        Themes <span class="registry-tab__count">({{ counts.theme }})</span>
      </button>
      <button
        type="button"
        role="tab"
        class="registry-tab"
        :class="{ '-active': activeTab === 'hook' }"
        :aria-selected="activeTab === 'hook'"
        @click="activeTab = 'hook'"
      >
        Hooks <span class="registry-tab__count">({{ counts.hook }})</span>
      </button>
    </div>

    <!-- Items Grid -->
    <div v-if="filteredItems.length > 0" class="registry-grid">
      <div
        v-for="item in filteredItems"
        :key="item.name"
        class="registry-card"
        :class="[`registry-card--${item.type.replace(/^registry:/, '')}`]"
      >
        <div class="registry-card__header">
          <div class="registry-card__title-group">
            <h3 class="registry-card__title">
              {{ item.title || item.name }}
            </h3>
            <span class="registry-card__badge" :data-type="item.type">
              {{ typeBadgeLabel(item.type) }}
            </span>
          </div>
          <a
            :href="`/r/${item.name}.json`"
            target="_blank"
            rel="noopener noreferrer"
            class="registry-card__json-btn"
            title="View JSON manifest"
          >
            JSON ↗
          </a>
        </div>

        <p class="registry-card__desc">
          {{ item.description }}
        </p>

        <!-- Dependencies -->
        <div v-if="item.dependencies && item.dependencies.length > 0" class="registry-card__deps">
          <span class="registry-card__deps-label">Deps:</span>
          <span v-for="dep in item.dependencies" :key="dep" class="registry-card__dep-pill">
            {{ dep }}
          </span>
        </div>

        <!-- Command Bar -->
        <div class="registry-card__command">
          <code class="registry-card__command-text">{{ getCommand(item.name) }}</code>
          <button
            type="button"
            class="registry-card__copy-btn"
            :class="{ '-copied': copiedItem === item.name }"
            @click="copyCommand(item.name)"
          >
            {{ copiedItem === item.name ? "Copied!" : "Copy" }}
          </button>
        </div>

        <!-- Expandable Details Toggle -->
        <div v-if="item.files || item.cssVars" class="registry-card__details-wrapper">
          <button
            type="button"
            class="registry-card__details-toggle"
            @click="toggleExpand(item.name)"
          >
            {{ expandedItem === item.name ? "Hide Preview ▲" : "Preview Details ▼" }}
          </button>

          <div v-if="expandedItem === item.name" class="registry-card__details-content">
            <!-- Files Preview -->
            <div v-if="item.files && item.files.length > 0" class="registry-card__file-preview">
              <div v-for="file in item.files" :key="file.path" class="registry-card__file">
                <div class="registry-card__file-header">
                  <span class="registry-card__file-path">{{ file.target || file.path }}</span>
                  <span class="registry-card__file-type">{{ file.type }}</span>
                </div>
                <pre v-if="file.content" class="registry-card__file-code"><code>{{ file.content }}</code></pre>
              </div>
            </div>

            <!-- CSS Vars Preview -->
            <div v-if="item.cssVars?.light" class="registry-card__vars-preview">
              <div class="registry-card__vars-header">Light Theme Tokens</div>
              <div class="registry-card__vars-grid">
                <div
                  v-for="(val, key) in item.cssVars.light"
                  :key="key"
                  class="registry-card__var-row"
                >
                  <span class="registry-card__var-key">--{{ key }}:</span>
                  <span class="registry-card__var-val">{{ val }}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Empty State -->
    <div v-else class="registry-empty">
