{"content":"<script setup lang="ts">
import { computed, ref, shallowRef, watch } from "vue";
import { useData } from "vitepress";
import catalogData from "../../../public/r/registry.json";
import { readHashParam, writeHashParam } from "../composables/useHashParams";
import { useHashParamRef } from "../composables/usePickerHelpers";

interface RegistryFile {
  path: string;
  type: string;
  content?: string;
  target?: string;
}

interface RegistryItem {
  $schema?: string;
  name: string;
  type:
    | "registry:base"
    | "registry:block"
    | "registry:component"
    | "registry:font"
    | "registry:lib"
    | "registry:hook"
    | "registry:ui"
    | "registry:page"
    | "registry:file"
    | "registry:style"
    | "registry:theme"
    | "registry:item";
  title?: string;
  description?: string;
  author?: string;
  dependencies?: string[];
  devDependencies?: string[];
  registryDependencies?: string[];
  files?: RegistryFile[];
  cssVars?: {
    theme?: Record<string, string>;
    light?: Record<string, string>;
    dark?: Record<string, string>;
  };
  css?: Record<string, Record<string, string>>;
  meta?: Record<string, unknown>;
}

type TabKey = "all" | "ui" | "theme" | "hook";

const { theme } = useData();
const t = computed(() => {
  const base = {
    title: "shadcn/ui Registry",
    subtitle:
      "Compatible components, themes, and behavior hooks conforming to the shadcn/ui registry specification. Add items directly to your shadcn/ui project via CLI.",
    tabAll: "All",
    tabComponents: "Components",
    tabThemes: "Themes",
    tabHooks: "Hooks",
    searchPlaceholder: "Filter components, themes, hooks…",
    cliLabel: "CLI:",
    copy: "Copy",
    copied: "Copied",
    depsLabel: "Deps:",
    previewDetails: "Preview details",
    previewTokens: "Token mappings (light)",
    viewJson: "JSON",
    emptyTitle: "No registry items match your search.",
    emptyReset: "Reset Filters",
  };
  const overrides = ((theme.value as Record<string, unknown>).registryBrowser ?? {}) as Record<
    string,
    unknown
  >;
  return { ...base, ...overrides };
});

const catalog = shallowRef(catalogData);
const items = computed<RegistryItem[]>(() => catalog.value.items as RegistryItem[]);

const search = useHashParamRef("r_q", "");
const pm = useHashParamRef("r_pm", "npx");

const initialTab = readHashParam("r_tab");
const activeTab = ref<TabKey>(
  initialTab === "ui" || initialTab === "theme" || initialTab === "hook"
    ? (initialTab as TabKey)
    : "all",
);
watch(activeTab, (tab) => writeHashParam("r_tab", tab, "all"));

const copiedItem = ref<string | null>(null);

const counts = computed(() => {
  const all = items.value.length;
  const ui = items.value.filter((i) => i.type === "registry:ui").length;
  const theme = items.value.filter(
    (i) => i.type === "registry:theme" || i.type === "registry:base",
  ).length;
  const hook = items.value.filter((i) => i.type === "registry:hook").length;
  return { all, ui, theme, hook };
});

const filteredItems = computed(() => {
  const query = search.value.trim().toLowerCase();
  return items.value.filter((item) => {
    // Tab filter
    if (activeTab.value === "ui" && item.type !== "registry:ui") return false;
    if (
      activeTab.value === "theme" &&
      item.type !== "registry:theme" &&
      item.type !== "registry:base"
    )
      return false;
    if (activeTab.value === "hook" && item.type !== "registry:hook") return false;

    // Search query filter
    if (!query) return true;
    const matchName = item.name.toLowerCase().includes(query);
    const matchTitle = (item.title ?? "").toLowerCase().includes(query);
    const matchDesc = (item.description ?? "").toLowerCase().includes(query);
    const matchDeps = (item.dependencies ?? []).some((d) => d.toLowerCase().includes(query));
    return matchName || matchTitle || matchDesc || matchDeps;
  });
});

function getCommand(name: string): string {
  const url = `https://pantoken.app/r/${name}.json`;
  switch (pm.value) {
    case "pnpm":
      return `pnpm dlx shadcn@latest add ${url}`;
    case "bun":
      return `bunx --bun shadcn@latest add ${url}`;
    case "npx":
    default:
      return `npx shadcn@latest add ${url}`;
  }
}

async function copyCommand(name: string) {
  const text = getCommand(name);
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      copiedItem.value = name;
      setTimeout(() => {
        if (copiedItem.value === name) {
          copiedItem.value = null;
        }
      }, 2000);
    } catch {
      // Ignore clipboard error
    }
  }
}

function typeBadgeLabel(type: RegistryItem["type"]): string {
  switch (type) {
    case "registry:ui":
      return "UI";
    case "registry:theme":
      return "Theme";
    case "registry:base":
      return "Base";
    case "registry:hook":
      return "Hook";
    default:
      return type.replace(/^registry:/, "");
  }
}

function badgeColorClass(type: RegistryItem["type"]): string {
  switch (type) {
    case "registry:ui":
      return "-color-brand";
    case "registry:theme":
    case "registry:base":
      return "-color-warning";
    case "registry:hook":
      return "-color-success";
    default:
      return "-color-info";
  }
}
</script>

<template>
  <div class="registry-page instui-view">
    <h1 class="instui-heading -level-h1 -variant-title-page" style="margin: 0 0 1rem">
